/* Online room credentials stay on this device; shared links contain only a room code. */
window.Online=(()=>{
'use strict';
const API='https://yirmi-tl-sepet-oyunu.dependablepin4.chatgpt.site';
const KEY='butce-online-room-v1',app=document.querySelector('#app'),G=Breakfast,LIST=CATALOG;
let credentials=null,state=null,active=false,timer=null,polling=false,busy=false,selection=0,lastSignature='',onExit=()=>{},setup={theme:'kahvalti',order:'random'},errorCount=0,pendingJoin=null;
const $=q=>document.querySelector(q);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const s=JSON.parse(localStorage.getItem(KEY));if(/^[A-Z2-9]{8}$/.test(s?.code)&&/^[0-9a-f]{64}$/.test(s?.token))credentials=s;}catch{}
function persist(){try{if(credentials)localStorage.setItem(KEY,JSON.stringify(credentials));else localStorage.removeItem(KEY);}catch{}}
function stop(){active=false;clearTimeout(timer);lastSignature='';}
function exit(){stop();onExit();window.scrollTo(0,0);}
function note(message){const n=$('#online-notice');if(n)n.textContent=message;}
function status(message,bad=false){const n=$('#connection-status');if(n){n.textContent=message;n.classList.toggle('bad',bad);}}
function randomToken(){return Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');}
async function request(path,body,auth=credentials){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);try{const headers={};if(body!==undefined)headers['Content-Type']='application/json';if(auth?.token)headers.Authorization='Bearer '+auth.token;const r=await fetch(API+path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal,cache:'no-store',credentials:'omit'});let data;try{data=await r.json();}catch{throw Error('Sunucuya ulaşılamadı. Biraz sonra tekrar dene.');}if(!r.ok){const e=Error(data.error||'İşlem tamamlanamadı.');e.status=r.status;throw e;}return data;}catch(e){if(e.name==='AbortError'||e instanceof TypeError)throw Error('İnternet bağlantını kontrol et. Tekrar deneyebilirsin.');throw e;}finally{clearTimeout(timeout);}}
function open(options={}){stop();setup={theme:options.theme||'kahvalti',order:options.order||'random'};onExit=options.onExit||onExit;active=true;state=null;selection=0;renderLobby(options.code||'');window.scrollTo(0,0);}
function renderLobby(code=''){
 const t=LIST.find(t=>t.id===setup.theme)||LIST[0];
 app.innerHTML=`<section class="online-lobby"><button class="secondary" id="online-back">← Kategorilere dön</button><div class="online-intro"><span class="eyebrow">2–8 OYUNCU. AYNI DÜELLO.</span><h1>Arkadaşını<br><em>oyuna çağır.</em></h1><p class="muted">Biriniz oda açsın, herkes kendi telefonundan katılsın.<br>Teklifler herkes onaylayınca açılsın.</p></div>${credentials?`<div class="resume-banner"><div><b>Açık odan: ${escape(credentials.code)}</b><span>Sayfayı yenilesen de oyuna dönebilirsin.</span></div><button class="secondary" id="reconnect-room">Odaya dön →</button></div>`:''}<div class="online-options"><section class="online-option"><span class="eyebrow">01 / ODA AÇ</span><h2>Oyunu sen başlat.</h2><p class="muted">${t.emoji} ${escape(t.name)} ile başlar.<br>Kategoriler ${setup.order==='random'?'rastgele':'sıra sıra'} gelir.</p><label class="setup-label" for="room-capacity">ODA KAPASİTESİ</label><select id="room-capacity" class="room-input">${[2,3,4,5,6,7,8].map(n=>`<option value="${n}" ${n===4?'selected':''}>${n} kişi</option>`).join('')}</select><button class="primary wide" id="create-room">Oda oluştur <span>↗</span></button></section><section class="online-option"><span class="eyebrow">02 / ODAYA KATIL</span><h2>Arkadaşına katıl.</h2><label class="setup-label" for="room-code">8 KARAKTERLİ ODA KODU</label><input id="room-code" class="room-input" placeholder="ABCD2345" maxlength="8" autocapitalize="characters" autocomplete="off" spellcheck="false" value="${escape(code)}"><button class="primary wide" id="join-room">Odaya katıl <span>→</span></button></section></div><p id="online-notice" class="online-notice" role="status"></p><p class="rules-note">Çevrimiçi oyun internet gerektirir · 2–8 kişi · Kişi başına 5 tur · Odalar 24 saat geçerlidir</p></section>`;
 $('#online-back').onclick=exit;
 $('#room-code').oninput=e=>e.target.value=e.target.value.toUpperCase().replace(/[^A-Z2-9]/g,'');
 $('#room-code').onkeydown=e=>{if(e.key==='Enter')$('#join-room').click();};
 $('#create-room').onclick=async()=>{if(busy)return;busy=true;$('#create-room').disabled=true;note('Oda açılıyor…');try{const data=await request('/v1/rooms',{...setup,maxPlayers:Number($('#room-capacity').value)},null);credentials={code:data.state.code,token:data.token};persist();accept(data.state);schedule();}catch(e){note(e.message);if($('#create-room'))$('#create-room').disabled=false;}finally{busy=false;}};
 $('#join-room').onclick=async()=>{if(busy)return;const code=$('#room-code').value.trim().toUpperCase();if(!/^[A-Z2-9]{8}$/.test(code)){note('8 karakterli oda kodunu eksiksiz yaz.');return;}busy=true;$('#join-room').disabled=true;note('Odaya katılınıyor…');if(!pendingJoin||pendingJoin.code!==code)pendingJoin={code,token:randomToken()};const secret=pendingJoin.token;try{const data=await request(`/v1/rooms/${code}/join`,{token:secret},null);credentials={code,token:secret};persist();accept(data.state);schedule();}catch(e){note(e.message);if($('#join-room'))$('#join-room').disabled=false;}finally{busy=false;}};
 if($('#reconnect-room'))$('#reconnect-room').onclick=async()=>{if(busy)return;busy=true;note('Odaya dönülüyor…');try{const data=await request(`/v1/rooms/${credentials.code}`);accept(data.state);schedule();}catch(e){note(e.message);if([401,404,410].includes(e.status)){credentials=null;persist();}}finally{busy=false;}};
}
function schedule(){clearTimeout(timer);if(active&&state&&state.status!=='closed')timer=setTimeout(poll,document.hidden?8000:1500);}
async function poll(){if(!active||polling||!credentials)return;polling=true;const current=credentials.code;try{const data=await request(`/v1/rooms/${current}`);if(active&&credentials?.code===current){errorCount=0;accept(data.state);status('● Bağlantı açık');}}catch(e){if(active){errorCount++;status('● Yeniden bağlanılıyor…',true);const n=$('#online-message');if(n)n.textContent=e.message+' Oyunun korunuyor.';if([401,404,410].includes(e.status)){state={...state,status:'closed',closedMessage:e.message};render();}}}finally{polling=false;schedule();}}
function accept(next){if(state&&next.rev<state.rev)return;const old=state;state=next;const sig=JSON.stringify([state.rev,state.role]);if(lastSignature!==sig){lastSignature=sig;if(!old||old.turnKey!==next.turnKey)selection=0;render();}status('● Bağlantı açık');}
async function action(which,extra={}){if(busy||!state||!credentials)return;busy=true;const expected=state.turnKey;const b=$('#online-confirm');if(b)b.disabled=true;try{const data=await request(`/v1/rooms/${credentials.code}/${which}`,{turnKey:expected,...extra});if(active){accept(data.state);status('● Bağlantı açık');}}catch(e){const n=$('#online-message');if(n)n.textContent=e.message;status('● Tekrar deneyebilirsin',true);}finally{busy=false;if($('#online-confirm'))$('#online-confirm').disabled=!!state?.ready?.[state.role];schedule();}}
const label=i=>`Oyuncu ${i+1}${state.role===i?' · Sen':''}`;
function player(p,i,final=false){const s=G.score(p),t=LIST.find(t=>t.id===state.game.themeId);return `<section class="player ${i===1?'rival':''}"><div class="player-head"><b>${label(i)}</b><span class="avatar">${i===0?'😎':'✌️'}</span></div><div class="wallet"><small>Kalan bütçe</small><div class="money">${p.money} <span>TL</span></div></div>${Visuals.scene(t.id,p.items,'online-'+i)}${Visuals.owned(p.items)}<div class="player-foot"><span>${p.items.length} parça</span><b>${s.total} puan</b></div>${final?`<div class="score-detail">Ürünler: ${s.base} puan<br>Çeşitlilik: +${s.variety} puan</div>`:''}</section>`;}
function top(){return `<div class="online-room-bar"><span>ODA <b>${state.code}</b><small>${label(state.role)} · ${state.joinedCount}/${state.maxPlayers} kişi</small></span><span id="connection-status">● Bağlantı açık</span><button class="secondary" id="online-menu">Menü</button></div>`;}
function bindTop(){$('#online-menu').onclick=exit;}
function history(){return state.game.history.length?`<details class="history"><summary>Geçmiş turlar (${state.game.history.length})</summary>${state.game.history.map(r=>`<div class="history-row"><span>${r.item.emoji} ${escape(r.item.name)}</span><span>${r.bids.join(' / ')} TL</span><span>${r.winner===null?'Herkes pas':`Oyuncu ${r.winner+1}`}</span></div>`).join('')}</details>`:'';}
function render(){
 if(!active||!state)return;
 if(state.status==='closed'){app.innerHTML=`${top()}<section class="online-intro"><span class="eyebrow">ODA KAPANDI</span><h2>Yeni bir düello açabilirsin.</h2><p class="muted">${escape(state.closedMessage||'Bir oyuncu odadan ayrıldı. Bu odadaki oyun sona erdi.')}</p><button class="primary" id="new-online-room">Yeni oda / başka oda →</button></section>`;bindTop();$('#new-online-room').onclick=()=>{credentials=null;persist();state=null;renderLobby();};return;}
 if(state.status==='waiting'){app.innerHTML=`${top()}<section class="waiting-room"><span class="waiting-icon">🌐</span><span class="eyebrow">ODA HAZIR</span><h2>Oyuncuları bekliyoruz.</h2><p class="muted">Bu kodu arkadaşlarınla paylaş.<br>En az iki kişi katılınca oda kurucusu oyunu başlatır. Tur sayısı katılan kişi sayısının 5 katıdır.</p><div class="big-room-code">${state.code}</div><div class="lobby-players">${Array.from({length:state.maxPlayers},(_,i)=>`<span class="lobby-seat ${i<state.joinedCount?'joined':''}">${i<state.joinedCount?'✓':'○'} Oyuncu ${i+1}${i===state.role?' · Sen':''}</span>`).join('')}</div><button class="primary" id="copy-invite">Davet bağlantısını kopyala ↗</button><p class="micro" id="copy-note">Davet bağlantısında gizli oyuncu anahtarın yer almaz.</p><div class="online-start-area">${state.role===0?`<button class="primary" id="start-online-game" ${state.joinedCount<2?'disabled':''}>${state.joinedCount<2?'En az bir arkadaşını bekliyoruz…':`Oyunu başlat (${state.joinedCount} kişi) →`}</button>`:'<p class="muted">Oda kurucusunun oyunu başlatması bekleniyor.</p>'}</div><p class="online-notice" id="online-message" role="status"></p><button class="secondary" id="leave-room">Odadan ayrıl</button></section>`;bindTop();$('#copy-invite').onclick=copyInvite;if($('#start-online-game'))$('#start-online-game').onclick=()=>action('start');$('#leave-room').onclick=()=>action('leave');return;}
 const g=state.game,t=LIST.find(t=>t.id===g.themeId),me=state.role,othersReady=state.ready.filter((v,i)=>i!==me&&v).length,othersSubmitted=state.submitted.filter((v,i)=>i!==me&&v).length;
 if(g.stage==='finished'){
  const w=G.winner(g),wins=g.players.map((_,i)=>state.results.filter(r=>r.winner===i).length),end=state.index+1>=state.queue.length,next=LIST.find(t=>t.id===state.queue[state.index+1]);
  app.innerHTML=`${top()}<section class="summary"><span class="eyebrow">${t.emoji} ${escape(t.name)} · SONUÇLAR</span><h1>${w===null?'Berabere!':w===me?'Bu düello<br><em>senin!</em>':`Oyuncu ${w+1}<br><em>kazandı!</em>`}</h1><div class="series-score"><span>Seri skoru</span><b>${wins.map((w,i)=>`Oyuncu ${i+1}: ${w}`).join(' · ')}</b><small>${state.results.length} kategori oynandı</small></div><div class="summary-players">${g.players.map((p,i)=>player(p,i,true)).join('')}</div><p class="muted">${end?'Tüm kategoriler tamamlandı. Birlikte yeni bir seriye başlayabilirsiniz.':`Sıradaki kategori: ${next.emoji} ${escape(next.name)}. Bütçeler yeniden 20 TL olur.`}</p><button class="primary" id="online-confirm" ${state.ready[me]?'disabled':''}>${state.ready[me]?'Diğer oyuncular bekleniyor…':end?'Yeni seri için hazırım →':'Sonraki kategoriye hazırım →'}</button><p id="online-message" class="online-notice" role="status"></p><button class="secondary" id="leave-room">Odadan ayrıl</button>${history()}</section>`;bindTop();$('#online-confirm').onclick=()=>action('advance');$('#leave-room').onclick=()=>action('leave');return;
 }
 const item=g.deck[g.round];app.innerHTML=`${top()}<div class="game-top"><div><span class="eyebrow">${t.emoji} ${escape(t.name.toLocaleUpperCase('tr'))}</span><div class="round">TUR ${g.round+1} / ${g.deck.length}<div class="dots" aria-hidden="true">${g.deck.map((_,i)=>`<span class="dot ${i<g.round?'done':i===g.round?'current':''}"></span>`).join('')}</div></div></div><span class="online-live-label">🌐 Çevrimiçi düello</span></div><div class="online-arena"><section class="auction"><span class="tag">${g.stage==='reveal'?'TEKLİFLER AÇILDI':'GİZLİ TEKLİFİNİ VER'}</span><div class="dish photo-dish" role="img" aria-label="${escape(item.name)}">${Visuals.item(item)}</div><h2>${escape(item.name)}</h2><div class="point-label">${escape(item.category)} • <b>${item.points} puan</b></div><div id="online-bid-area"></div></section><div class="online-players">${g.players.map((p,i)=>player(p,i)).join('')}</div></div><p id="online-message" class="online-notice" role="status"></p><div class="status-bar"><span>🤫</span><p>Herkes teklif verene kadar tutarlar gizlidir. Eşitlik önceliği bu tur <b>Oyuncu ${g.round%g.players.length+1}</b> ile başlar ve oyuncu sırasıyla devam eder.</p></div><p class="rules-note">${state.index+1}. kategori / ${state.queue.length} · ${state.order==='random'?'Rastgele':'Sıralı'} akış · Her farklı ürün grubu +2 puan</p>${history()}<div class="online-leave"><button class="secondary" id="leave-room">Odadan ayrıl</button></div>`;
 bindTop();$('#leave-room').onclick=()=>action('leave');
 const area=$('#online-bid-area');
 if(g.stage==='reveal'){const r=g.history[g.history.length-1];area.innerHTML=`<div class="result-bids">${r.bids.map((b,i)=>`<div>${label(i)}<b>${b===0?'Pas':b+' TL'}</b></div>`).join('')}</div><p class="win-label">${r.winner===null?'Herkes pas geçti.':r.winner===me?'Ürünü sen aldın!':`Oyuncu ${r.winner+1} aldı!`}</p><button class="primary" id="online-confirm" ${state.ready[me]?'disabled':''}>${state.ready[me]?'Oyuncular bekleniyor…':g.round===g.deck.length-1?'Sonuçları görmeye hazırım →':'Sonraki ürüne hazırım →'}</button><p class="turn-note">${state.ready.filter(Boolean).length}/${g.players.length} oyuncu hazır. Herkes onaylayınca devam eder.</p>`;$('#online-confirm').onclick=()=>action('advance');return;}
 if(state.submitted[me]){area.innerHTML=`<div class="bid-waiting"><span>🔒</span><h3>Teklifin kilitlendi.</h3><p class="muted">${state.submitted.filter(Boolean).length}/${g.players.length} teklif tamamlandı.<br>Diğer oyuncuların teklifleri bekleniyor.</p></div>`;return;}
 const money=g.players[me].money;selection=Math.min(money,selection);area.innerHTML=`<label class="bid-label" for="online-range">Senin teklifin · Bütçen ${money} TL</label><div class="stepper"><button id="online-minus" aria-label="Teklifi azalt">−</button><div class="bid-number"><span id="online-value">${selection}</span> <small>TL</small></div><button id="online-plus" aria-label="Teklifi artır">+</button></div><input type="range" id="online-range" min="0" max="${money}" step="1" value="${selection}" aria-label="Gizli teklif TL"><div class="bid-shortcuts"><button data-online-bid="0">Pas</button><button data-online-bid="${Math.min(1,money)}">1 TL</button><button data-online-bid="${Math.min(3,money)}">${Math.min(3,money)} TL</button><button data-online-bid="${money}">Tümü (${money} TL)</button></div><button class="primary" id="online-confirm"></button><p class="turn-note">${othersSubmitted}/${g.players.length-1} rakip teklif verdi. Tutarlar gizli. Onaylanan teklif değiştirilemez.</p>`;
 function update(){selection=Math.max(0,Math.min(money,selection));$('#online-range').value=selection;$('#online-value').textContent=selection;$('#online-confirm').textContent=selection===0?'Pas geç ve kilitle →':`${selection} TL teklif ver →`;$('#online-minus').disabled=selection===0;$('#online-plus').disabled=selection===money;}
 $('#online-minus').onclick=()=>{selection--;update();};$('#online-plus').onclick=()=>{selection++;update();};$('#online-range').oninput=e=>{selection=Number(e.target.value);update();};document.querySelectorAll('[data-online-bid]').forEach(b=>b.onclick=()=>{selection=Number(b.dataset.onlineBid);update();});$('#online-confirm').onclick=()=>action('bid',{bid:selection});update();
}
async function copyInvite(){const url=new URL('./',location.href);url.searchParams.set('oda',state.code);try{await navigator.clipboard.writeText(url.href);$('#copy-note').textContent='Bağlantı kopyalandı! Arkadaşına gönderebilirsin.';}catch{$('#copy-note').textContent=url.href;}}
document.addEventListener('visibilitychange',()=>{if(active&&state&&!document.hidden)poll();});
window.addEventListener('online',()=>{if(active&&state)poll();});
return {open,stop,hasSaved:()=>!!credentials};
})();
